-- C11 / P11.6 additive publication lifecycle evidence. Repository-only; no production application authorized.
create table if not exists public.command_center_book_publication_lifecycle_history(
 owner_id uuid not null references auth.users(id) on delete cascade,
 event_id text not null check(btrim(event_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), edition text not null check(btrim(edition)<>''), format text not null, provider_key text not null check(btrim(provider_key)<>''), provider_listing_id text,
 state text not null check(state in ('not_prepared','prepared','upload_ready','uploaded','draft','submitted','in_review','changes_required','blocked','rejected','approved','live','unpublished','archived','superseded')),
 provider_receipt_ref text, provider_publication_ref text, provider_timestamp timestamptz, error_refs text[] not null default '{}', correction_refs text[] not null default '{}', evidence_refs text[] not null default '{}', uncertainty text, supersedes_event_id text, observed_at timestamptz not null, last_verified_at timestamptz not null,
 primary key(owner_id,event_id), check(last_verified_at<=observed_at), check(provider_listing_id is null or btrim(provider_listing_id)<>''), check(provider_receipt_ref is null or btrim(provider_receipt_ref)<>''), check(provider_publication_ref is null or btrim(provider_publication_ref)<>''), check(supersedes_event_id is null or btrim(supersedes_event_id)<>'')
);
create or replace view public.command_center_book_publication_lifecycle_current with(security_invoker=true) as select distinct on(owner_id,project_id,book_id,edition,format,provider_key) * from public.command_center_book_publication_lifecycle_history order by owner_id,project_id,book_id,edition,format,provider_key,observed_at desc,event_id desc;
create or replace function public.command_center_reject_book_publication_lifecycle_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Publication lifecycle evidence is immutable'; end $$;
drop trigger if exists command_center_book_publication_lifecycle_immutable on public.command_center_book_publication_lifecycle_history;
create trigger command_center_book_publication_lifecycle_immutable before update or delete on public.command_center_book_publication_lifecycle_history for each row execute function public.command_center_reject_book_publication_lifecycle_mutation();
alter table public.command_center_book_publication_lifecycle_history enable row level security; revoke all on table public.command_center_book_publication_lifecycle_history from public,anon,authenticated; grant select,insert on table public.command_center_book_publication_lifecycle_history to authenticated; grant select on table public.command_center_book_publication_lifecycle_current to authenticated;
create policy p11_6_book_publication_lifecycle_owner on public.command_center_book_publication_lifecycle_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
